export const PatchedAlertCategoryRequestSchema = {
    type: 'object',
    description: `Basis-Serializer für alle ManagedObject Detail-Endpoints.

Enthält alle generischen Felder eines ManagedObjects.
Subclasses erweitern diese Liste mit model-spezifischen Feldern.

Inkludiert:
- Alle BaseObject Felder (id, name, display_name, labels, annotations, timestamps)
- Alle ManagedObject Felder (state, reconciliation, discovery, repair, conditions, etc.)
- organization/workspace als generische ManagedObject-Referenzen (mit URL)
- created: Kombifeld (created_at, created_at_humanized, created_by)
- url: Absolute URL zum Object (via get_absolute_url())

Usage:
    class K8sClusterDetailSerializer(ManagedObjectDetailSerializer):
        class Meta(ManagedObjectDetailSerializer.Meta):
            model = K8sCluster
            fields = ManagedObjectDetailSerializer.Meta.fields + ['kubeconfig', 'nodes']`,
    properties: {
        name: {
            type: 'string',
            description: 'Object name',
            maxLength: 253
        },
        display_name: {
            type: 'string',
            nullable: true,
            description: 'The display name is used to display the object in the UI. It can be different from the name.'
        },
        labels: {
            nullable: true
        },
        annotations: {
            nullable: true
        },
        debug_mode: {
            type: 'boolean',
            description: 'Persists all Object Logs in the database'
        },
        provider: {
            '$ref': '#/components/schemas/ProviderEnum'
        },
        provider_reference: {
            type: 'string',
            nullable: true
        },
        provider_id: {
            type: 'string',
            nullable: true
        },
        reconciliation_enabled: {
            type: 'boolean'
        },
        platform_service: {
            type: 'boolean'
        },
        kind: {
            '$ref': '#/components/schemas/GenericObjectKindEnum'
        },
        tolerations: {
            description: 'Tolerations match conditions. If a toleration for a condition exists for an object, the condition will not be applied.'
        },
        archived: {
            type: 'boolean',
            description: 'Archived objects are not shown in the UI and are not managed by the API.'
        },
        archived_at: {
            type: 'string',
            format: 'date-time',
            nullable: true
        },
        archived_reason: {
            type: 'string',
            nullable: true,
            description: 'The reason why the object was archived'
        },
        criticality: {
            nullable: true,
            description: `Criticality level. Null = inherit from workspace, then org. Explicit value overrides inheritance.

* \`high\` - High
* \`medium\` - Medium
* \`low\` - Low`,
            oneOf: [
                {
                    '$ref': '#/components/schemas/CriticalityEnum'
                },
                {
                    '$ref': '#/components/schemas/BlankEnum'
                },
                {
                    '$ref': '#/components/schemas/NullEnum'
                }
            ]
        },
        target_availability: {
            type: 'string',
            format: 'decimal',
            pattern: '^-?\\d{0,3}(?:\\.\\d{0,2})?$',
            nullable: true,
            description: 'Target availability in % (overrides SystemConfig default). Null = use SystemConfig DEFAULT_TARGET_AVAILABILITY.'
        },
        slo_target: {
            type: 'string',
            format: 'decimal',
            pattern: '^-?\\d{0,3}(?:\\.\\d{0,2})?$',
            nullable: true,
            description: 'Internal SLO target in %. Null = use SystemConfig DEFAULT_SLO_TARGET'
        },
        slo_availability: {
            type: 'string',
            format: 'decimal',
            pattern: '^-?\\d{0,3}(?:\\.\\d{0,2})?$',
            description: 'Calculated SLO availability in % (updated in reconcile)'
        },
        sla_target: {
            type: 'string',
            format: 'decimal',
            pattern: '^-?\\d{0,3}(?:\\.\\d{0,2})?$',
            nullable: true,
            description: 'Contractual SLA target in %. Null = use SystemConfig DEFAULT_SLA_TARGET'
        },
        sla_availability: {
            type: 'string',
            format: 'decimal',
            pattern: '^-?\\d{0,3}(?:\\.\\d{0,2})?$',
            description: 'Calculated SLA availability in % (updated in reconcile)'
        },
        description: {
            type: 'string'
        },
        sort_order: {
            type: 'integer',
            maximum: 2147483647,
            minimum: 0
        },
        active: {
            type: 'boolean',
            description: 'Inactive categories are skipped when resolving new mappings.'
        }
    }
} as const;

