export const S3BucketRegionRequestSchema = {
    type: 'object',
    description: `Serializer für Bucket-Erstellung mit Region-UUID.

Accepts \`region\` as a workspaces.Region UUID (write-only) — resolves via
region.legacy_s3_cluster to the backing S3Cluster. The bucket's region FK
is NOT set at creation time; it is populated lazily by ensure_region() in
reconciliation (Spec 333 Phase 2b).
Falls back to SystemConfig.default_s3_bucket_cluster when region is omitted.
Agent tokens: workspace/organization auto-assigned via perform_create().
Regular users: workspace/organization required in request body.`,
    properties: {
        name: {
            type: 'string',
            minLength: 1,
            pattern: '^[a-z0-9]+(?:-[a-z0-9]+)*$'
        },
        region: {
            type: 'string',
            format: 'uuid',
            writeOnly: true,
            nullable: true,
            description: 'UUID of the workspaces.Region where the bucket should be created. If omitted, the system default S3 cluster is used.'
        },
        organization: {
            type: 'string',
            format: 'uuid',
            nullable: true,
            description: 'The ID of the organisation that owns this bucket'
        },
        workspace: {
            type: 'string',
            format: 'uuid',
            nullable: true
        },
        labels: {
            nullable: true
        },
        annotations: {
            nullable: true
        },
        cors_allow_all: {
            type: 'boolean',
            description: 'Apply a permissive CORS configuration to this bucket. Only effective for Ceph clusters.'
        }
    },
    required: ['name']
} as const;

